import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.Ch4PdLd_.js";const m=JSON.parse('{"title":"Remote SSH","description":"","frontmatter":{},"headers":[],"relativePath":"gui/remote.md","filePath":"gui/remote.md"}'),d={name:"gui/remote.md"};function n(i,e,c,s,l,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="remote-ssh" tabindex="-1">Remote SSH <a class="header-anchor" href="#remote-ssh" aria-label="Permalink to &quot;Remote SSH&quot;">​</a></h1><p>GUI 可以通过 SSH 打开 Linux 主机上的项目。界面在本机，nek 和项目文件都在远端：文件读写、命令和模型调用都在远端执行。</p><h2 id="requirements" tabindex="-1">远端需要什么 <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;远端需要什么 {#requirements}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>系统</td><td>Linux x64</td></tr><tr><td>SSH</td><td>能从本机登录，支持密钥、ssh-agent 和密码；会读取本机 <code>~/.ssh/config</code>，包括多跳 <code>ProxyJump</code></td></tr><tr><td>nek</td><td>0.5.1-beta.7 或更新版本。没有安装或版本太旧时，连接对话框可以直接在远端安装，并显示安装日志；也可以复制手动安装命令自己执行</td></tr></tbody></table><p>第一次连接时，GUI 会显示主机指纹（<code>SHA256:...</code>）请你确认。主机指纹之后发生变化时，连接会被阻断。</p><h2 id="server" tabindex="-1">远端组件 <a class="header-anchor" href="#server" aria-label="Permalink to &quot;远端组件 {#server}&quot;">​</a></h2><p>GUI 需要在远端运行一个小的服务进程，安装在 <code>~/.nek/gui-server/</code>。首次连接或 GUI 升级后：</p><ol><li>远端直接从 <a href="https://github.com/deepdarkpaw/nekcode-gui/releases" target="_blank" rel="noreferrer">nekcode-gui Releases</a> 下载与本机 GUI 同版本的 <code>nekcode-gui-server-*.tar.gz</code> 组件；</li><li>每个文件都用安装包自带的 SHA256 清单校验，校验不通过就不会使用；</li><li>远端无法访问 GitHub 时，GUI 会显示失败原因，然后改为从本机上传这些组件。</li></ol><p>组件已经是当前版本时，再次连接不会重新下载。</p><h2 id="config" tabindex="-1">配置在哪一边 <a class="header-anchor" href="#config" aria-label="Permalink to &quot;配置在哪一边 {#config}&quot;">​</a></h2><p>远程项目使用<strong>远端主机上的 nek 配置</strong>（远端的 <code>~/.nek/agent/</code> 和项目里的 <code>.nek/</code>）。在远程项目中打开设置，服务商、模型、Skill、MCP 等页面读写的是远端的这些文件，和在远端终端里运行 <code>nek</code> 看到的一致。本机的 nek 配置不会被带到远端。</p><h2 id="reconnect" tabindex="-1">断线与重连 <a class="header-anchor" href="#reconnect" aria-label="Permalink to &quot;断线与重连 {#reconnect}&quot;">​</a></h2><p>连接断开后 GUI 会按间隔自动重连，标题栏显示当前状态，也可以手动重试或取消。</p>',13)])])}const p=t(d,[["render",n]]);export{m as __pageData,p as default};
